def cache_sim(capacity, ttl, ops):
    from collections import OrderedDict

    cache = OrderedDict()  # key -> (value, write_time)
    results = []

    for op in ops:
        if op[0] == 'put':
            _, t, key, value = op
            # Remove the key if it exists (to re-insert it at the end)
            if key in cache:
                del cache[key]
            # If cache is at capacity and key is new, evict LRU
            elif len(cache) >= capacity:
                cache.popitem(last=False)
            # Add the new entry
            cache[key] = (value, t)

        elif op[0] == 'get':
            _, t, key = op
            if key in cache:
                value, write_time = cache[key]
                # Check if entry has expired
                if t < write_time + ttl:
                    # Move to end (most recently used)
                    del cache[key]
                    cache[key] = (value, write_time)
                    results.append(value)
                else:
                    # Entry expired
                    del cache[key]
                    results.append(-1)
            else:
                results.append(-1)

    return results

